  `peer_as` bigint unsigned NOT NULL,
  `local_as` bigint unsigned NOT NULL DEFAULT '0',
  `afi` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `safi` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `state` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unknown',
