  `range_start` datetime(3) NOT NULL,
  `range_end` datetime(3) NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `computed_value` double DEFAULT NULL,
  `total_bytes` bigint unsigned DEFAULT NULL,
  `computed_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_billing_periods_account_range` (`billing_account_id`,`range_start`,`range_end`),
  KEY `idx_billing_periods_tenant_status` (`tenant_id`,`status`),
  CONSTRAINT `fk_billing_periods_account` FOREIGN KEY (`billing_account_id`) REFERENCES `billing_accounts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_billing_periods_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `billing_periods_chk_1` CHECK ((`status` in ('open','computed','approved','void')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `collector_agents` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `module_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL,
  `agent_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mode` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `endpoint` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `observed_health` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unknown',
  `auth_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'token',
  `token_hash` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pending_token_hash` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `certificate_fingerprint` varchar(190) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pending_certificate_fingerprint` varchar(190) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pending_credential_expires_at` datetime(3) DEFAULT NULL,
  `capabilities_json` json DEFAULT NULL,
  `capabilities_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `capability_schema_version` smallint unsigned NOT NULL DEFAULT '1',
  `software_version` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `agent_api_version` smallint unsigned NOT NULL DEFAULT '1',
  `plan_schema_min` smallint unsigned NOT NULL DEFAULT '1',
  `plan_schema_max` smallint unsigned NOT NULL DEFAULT '1',
  `boot_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `runtime_schema_version` smallint unsigned NOT NULL DEFAULT '0',
  `heartbeat_sequence` bigint unsigned NOT NULL DEFAULT '0',
  `heartbeat_sent_at` datetime(3) DEFAULT NULL,
  `clock_offset_ms` bigint DEFAULT NULL,
  `runtime_observation_json` json DEFAULT NULL,
  `runtime_observation_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `heartbeat_payload_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `config_version` bigint unsigned NOT NULL DEFAULT '0',
  `acknowledged_config_version` bigint unsigned NOT NULL DEFAULT '0',
  `last_good_config_version` bigint unsigned NOT NULL DEFAULT '0',
  `plan_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `plan_expires_at` datetime(3) DEFAULT NULL,
  `last_seen_at` datetime(3) DEFAULT NULL,
  `last_error_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_error_detail` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `row_version` bigint unsigned NOT NULL DEFAULT '1',
  `created_by` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updated_by` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted_at` datetime(3) DEFAULT NULL,
  `purge_after` datetime(3) DEFAULT NULL,
  `live_identity` tinyint GENERATED ALWAYS AS (if((`deleted_at` is null),1,NULL)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_collector_agent_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uq_collector_name` (`tenant_id`,`module_key`,`name`,`live_identity`),
  KEY `idx_collector_health` (`tenant_id`,`status`,`observed_health`,`last_seen_at`),
  CONSTRAINT `fk_collector_agent_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_collector_pending_credential_expiry` CHECK ((((`pending_token_hash` is not null) or (`pending_certificate_fingerprint` is not null)) = (`pending_credential_expires_at` is not null))),
  CONSTRAINT `chk_collector_pending_credential_kind` CHECK ((((`pending_token_hash` is null) or (`auth_type` = 'token')) and ((`pending_certificate_fingerprint` is null) or (`auth_type` = 'mtls')))),
  CONSTRAINT `chk_collector_runtime_payload` CHECK ((((`runtime_schema_version` = 0) and (`heartbeat_sequence` = 0) and (`heartbeat_sent_at` is null) and (`clock_offset_ms` is null) and (`runtime_observation_json` is null) and (`runtime_observation_hash` = '') and (`heartbeat_payload_hash` = '')) or ((`runtime_schema_version` > 0) and (`heartbeat_sequence` > 0) and (`heartbeat_sent_at` is not null) and (`clock_offset_ms` is not null) and (`capabilities_json` is not null) and (char_length(`capabilities_hash`) = 64) and (`runtime_observation_json` is not null) and (char_length(`runtime_observation_hash`) = 64) and (char_length(`heartbeat_payload_hash`) = 64)))),
  CONSTRAINT `collector_agents_chk_1` CHECK ((`mode` in ('push','pull','listen'))),
  CONSTRAINT `collector_agents_chk_10` CHECK (((`auth_type` = 'mtls') = (`certificate_fingerprint` is not null))),
  CONSTRAINT `collector_agents_chk_2` CHECK ((`status` in ('pending','active','suspended','revoked','deleted'))),
  CONSTRAINT `collector_agents_chk_3` CHECK (((`status` = 'deleted') = (`deleted_at` is not null))),
  CONSTRAINT `collector_agents_chk_4` CHECK ((`observed_health` in ('unknown','warming','healthy','degraded','stale','unavailable'))),
  CONSTRAINT `collector_agents_chk_5` CHECK ((`plan_schema_min` <= `plan_schema_max`)),
  CONSTRAINT `collector_agents_chk_6` CHECK ((`last_good_config_version` <= `acknowledged_config_version`)),
  CONSTRAINT `collector_agents_chk_7` CHECK ((`acknowledged_config_version` <= `config_version`)),
  CONSTRAINT `collector_agents_chk_8` CHECK ((`auth_type` in ('token','mtls'))),
  CONSTRAINT `collector_agents_chk_9` CHECK (((`auth_type` = 'token') = (`token_hash` is not null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `collector_bindings` (
  `collector_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `binding_role` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'collect',
  `config_json` json DEFAULT NULL,
  `row_version` bigint unsigned NOT NULL DEFAULT '1',
  `created_by` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updated_by` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`collector_id`,`resource_type`,`resource_id`),
  KEY `idx_collector_binding_resource` (`tenant_id`,`resource_type`,`resource_id`,`binding_role`),
  KEY `fk_collector_binding_collector` (`tenant_id`,`collector_id`),
  CONSTRAINT `fk_collector_binding_collector` FOREIGN KEY (`tenant_id`, `collector_id`) REFERENCES `collector_agents` (`tenant_id`, `id`) ON DELETE CASCADE,
  CONSTRAINT `fk_collector_binding_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `collector_enrollment_secrets` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `secret_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `module_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `agent_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mode` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `collector_name` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expires_at` datetime(3) NOT NULL,
  `used_at` datetime(3) DEFAULT NULL,
  `used_by_collector_id` char(26) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_collector_enrollment_tenant` (`tenant_id`,`expires_at`),
  CONSTRAINT `fk_collector_enrollment_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `collector_enrollment_secrets_chk_1` CHECK (((`used_at` is null) = (`used_by_collector_id` is null))),
  CONSTRAINT `collector_enrollment_secrets_chk_2` CHECK ((`mode` in ('push','pull','listen')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `collector_ownership_transfers` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `exporter_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `old_collector_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `new_collector_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `old_plan_revision` bigint unsigned NOT NULL,
  `old_revoke_plan_revision` bigint unsigned NOT NULL,
  `new_plan_revision` bigint unsigned NOT NULL,
  `old_ownership_epoch` bigint unsigned NOT NULL,
  `new_ownership_epoch` bigint unsigned NOT NULL,
  `old_principal_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `max_clock_skew_ms` bigint unsigned NOT NULL,
  `approval_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requested_by` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `old_owner_boot_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `old_owner_drain_config_version` bigint unsigned DEFAULT NULL,
  `old_owner_drained_at` datetime(3) DEFAULT NULL,
  `drain_receipt_sha256` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `row_version` bigint unsigned NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_collector_ownership_transfer_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uq_collector_ownership_transfer_epoch` (`tenant_id`,`exporter_id`,`old_ownership_epoch`),
  KEY `idx_collector_ownership_transfer_new` (`tenant_id`,`exporter_id`,`new_ownership_epoch`),
  KEY `fk_collector_ownership_transfer_old_plan` (`tenant_id`,`old_collector_id`,`old_plan_revision`),
  KEY `fk_collector_ownership_transfer_old_revoke_plan` (`tenant_id`,`old_collector_id`,`old_revoke_plan_revision`),
  KEY `fk_collector_ownership_transfer_new_plan` (`tenant_id`,`new_collector_id`,`new_plan_revision`),
  KEY `fk_collector_ownership_transfer_principal` (`tenant_id`,`old_principal_id`),
  KEY `fk_collector_ownership_transfer_requester` (`requested_by`),
  CONSTRAINT `fk_collector_ownership_transfer_new_collector` FOREIGN KEY (`tenant_id`, `new_collector_id`) REFERENCES `collector_agents` (`tenant_id`, `id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_collector_ownership_transfer_new_plan` FOREIGN KEY (`tenant_id`, `new_collector_id`, `new_plan_revision`) REFERENCES `collector_plan_revisions` (`tenant_id`, `collector_id`, `config_version`) ON DELETE RESTRICT,
  CONSTRAINT `fk_collector_ownership_transfer_old_collector` FOREIGN KEY (`tenant_id`, `old_collector_id`) REFERENCES `collector_agents` (`tenant_id`, `id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_collector_ownership_transfer_old_plan` FOREIGN KEY (`tenant_id`, `old_collector_id`, `old_plan_revision`) REFERENCES `collector_plan_revisions` (`tenant_id`, `collector_id`, `config_version`) ON DELETE RESTRICT,
  CONSTRAINT `fk_collector_ownership_transfer_old_revoke_plan` FOREIGN KEY (`tenant_id`, `old_collector_id`, `old_revoke_plan_revision`) REFERENCES `collector_plan_revisions` (`tenant_id`, `collector_id`, `config_version`) ON DELETE RESTRICT,
  CONSTRAINT `fk_collector_ownership_transfer_principal` FOREIGN KEY (`tenant_id`, `old_principal_id`) REFERENCES `collector_service_principals` (`tenant_id`, `id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_collector_ownership_transfer_requester` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_collector_ownership_transfer_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `collector_ownership_transfers_chk_1` CHECK ((`old_collector_id` <> `new_collector_id`)),
  CONSTRAINT `collector_ownership_transfers_chk_2` CHECK ((`old_plan_revision` > 0)),
  CONSTRAINT `collector_ownership_transfers_chk_3` CHECK ((`old_revoke_plan_revision` > `old_plan_revision`)),
  CONSTRAINT `collector_ownership_transfers_chk_4` CHECK ((`new_plan_revision` > 0)),
  CONSTRAINT `collector_ownership_transfers_chk_5` CHECK ((`old_ownership_epoch` > 0)),
  CONSTRAINT `collector_ownership_transfers_chk_6` CHECK ((`new_ownership_epoch` > `old_ownership_epoch`)),
  CONSTRAINT `collector_ownership_transfers_chk_7` CHECK (((`old_owner_drained_at` is null) = (`old_owner_boot_id` is null))),
  CONSTRAINT `collector_ownership_transfers_chk_8` CHECK (((`old_owner_drained_at` is null) = (`old_owner_drain_config_version` is null))),
  CONSTRAINT `collector_ownership_transfers_chk_9` CHECK (((`old_owner_drained_at` is null) = (`drain_receipt_sha256` is null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `collector_plan_revisions` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `collector_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `config_version` bigint unsigned NOT NULL,
  `plan_schema_version` smallint unsigned NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `spec_json` json NOT NULL,
  `spec_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `signing_key_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `signature` varbinary(512) DEFAULT NULL,
  `validation_json` json DEFAULT NULL,
  `not_before` datetime(3) DEFAULT NULL,
  `expires_at` datetime(3) DEFAULT NULL,
  `supersedes_config_version` bigint unsigned DEFAULT NULL,
  `created_by` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updated_by` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `row_version` bigint unsigned NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `activated_at` datetime(3) DEFAULT NULL,
  `retired_at` datetime(3) DEFAULT NULL,
  `active_identity` tinyint GENERATED ALWAYS AS (if((`status` = 'active'),1,NULL)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_collector_plan_version` (`collector_id`,`config_version`),
  UNIQUE KEY `uq_collector_plan_tenant_version` (`tenant_id`,`collector_id`,`config_version`),
  UNIQUE KEY `uq_collector_active_plan` (`collector_id`,`active_identity`),
  KEY `idx_collector_plan_hash` (`collector_id`,`spec_hash`),
  KEY `idx_collector_plan_status` (`collector_id`,`status`,`config_version`),
  CONSTRAINT `fk_collector_plan_collector` FOREIGN KEY (`tenant_id`, `collector_id`) REFERENCES `collector_agents` (`tenant_id`, `id`) ON DELETE CASCADE,
  CONSTRAINT `fk_collector_plan_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `collector_plan_revisions_chk_1` CHECK ((`status` in ('draft','validated','active','retired','rejected'))),
  CONSTRAINT `collector_plan_revisions_chk_2` CHECK ((`config_version` > 0)),
  CONSTRAINT `collector_plan_revisions_chk_3` CHECK ((`plan_schema_version` > 0)),
  CONSTRAINT `collector_plan_revisions_chk_4` CHECK (((`status` <> 'active') or ((`signature` is not null) and (`activated_at` is not null) and (`expires_at` is not null)))),
  CONSTRAINT `collector_plan_revisions_chk_5` CHECK (((`status` <> 'retired') or (`retired_at` is not null))),
  CONSTRAINT `collector_plan_revisions_chk_6` CHECK (((`expires_at` is null) or (`not_before` is null) or (`expires_at` > `not_before`))),
  CONSTRAINT `collector_plan_revisions_chk_7` CHECK (((`supersedes_config_version` is null) or (`supersedes_config_version` < `config_version`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `collector_service_principals` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `collector_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
