  `grant_operation_key` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `grant_request_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
