  `write_revoked_at` datetime(3) DEFAULT NULL,
  `revoke_operation_key` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `revoke_receipt_ref` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `revoke_receipt_sha256` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `acl_propagation_delay_ms` bigint unsigned NOT NULL,
  `created_by` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updated_by` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `row_version` bigint unsigned NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_collector_service_principal_tenant_id` (`tenant_id`,`id`),
  UNIQUE KEY `uq_collector_service_principal_ref` (`service_type`,`principal_ref`),
  UNIQUE KEY `uq_collector_principal_grant_operation` (`grant_operation_key`),
  UNIQUE KEY `uq_collector_principal_revoke_operation` (`revoke_operation_key`),
  KEY `idx_collector_service_principal_owner` (`tenant_id`,`collector_id`,`service_type`,`status`),
  KEY `fk_collector_service_principal_creator` (`created_by`),
  KEY `fk_collector_service_principal_updater` (`updated_by`),
  CONSTRAINT `fk_collector_service_principal_collector` FOREIGN KEY (`tenant_id`, `collector_id`) REFERENCES `collector_agents` (`tenant_id`, `id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_collector_service_principal_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_collector_service_principal_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_collector_service_principal_updater` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `collector_service_principals_chk_1` CHECK ((`service_type` = 'kafka')),
  CONSTRAINT `collector_service_principals_chk_2` CHECK ((`status` in ('active','revoked'))),
  CONSTRAINT `collector_service_principals_chk_3` CHECK (((`status` = 'revoked') = (`write_revoked_at` is not null))),
  CONSTRAINT `collector_service_principals_chk_4` CHECK (((`status` = 'revoked') = (`revoke_receipt_ref` is not null))),
  CONSTRAINT `collector_service_principals_chk_5` CHECK (((`status` = 'revoked') = (`revoke_receipt_sha256` is not null))),
  CONSTRAINT `collector_service_principals_chk_6` CHECK (((`status` = 'revoked') = (`revoke_operation_key` is not null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

