CREATE TABLE IF NOT EXISTS `export_tasks` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_by` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_id` char(26) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `port_id` char(26) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `period_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `range_start` datetime(3) NOT NULL,
  `range_end` datetime(3) NOT NULL,
