  `aggregation` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value_mode` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'corrected',
  `format` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'csv',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `file_ref` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `checksum` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `size_bytes` bigint unsigned DEFAULT NULL,
  `expires_at` datetime(3) DEFAULT NULL,
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_export_tasks_tenant_created` (`tenant_id`,`created_at`),
  KEY `idx_export_tasks_status` (`tenant_id`,`status`),
  KEY `idx_export_tasks_expires` (`expires_at`),
  KEY `fk_export_tasks_user` (`created_by`),
  KEY `fk_export_tasks_target` (`target_id`),
  KEY `fk_export_tasks_port` (`port_id`),
  CONSTRAINT `fk_export_tasks_port` FOREIGN KEY (`port_id`) REFERENCES `network_ports` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_export_tasks_target` FOREIGN KEY (`target_id`) REFERENCES `targets` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_export_tasks_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_export_tasks_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `export_tasks_chk_1` CHECK ((`period_type` in ('day','month','fixed','custom'))),
  CONSTRAINT `export_tasks_chk_2` CHECK ((`aggregation` in ('p95_5m','avg_5m','fourth_peak_5m','daily_p95','daily_avg','total_bytes'))),
  CONSTRAINT `export_tasks_chk_3` CHECK ((`value_mode` in ('corrected','raw','both'))),
  CONSTRAINT `export_tasks_chk_4` CHECK ((`format` = 'csv'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

