  `row_version` bigint unsigned NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`tenant_id`,`job_type`,`partition_key`),
  CONSTRAINT `fk_operation_job_watermark_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `operation_jobs` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` char(26) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `scope_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'tenant',
  `job_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'queued',
  `idempotency_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `idempotency_domain` char(26) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (coalesce(`tenant_id`,_utf8mb4'__system__')) VIRTUAL,
  `request_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `progress_total` bigint unsigned DEFAULT NULL,
  `progress_done` bigint unsigned NOT NULL DEFAULT '0',
  `checkpoint_json` json NOT NULL,
  `result_ref` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lease_owner` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lease_token` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lease_expires_at` datetime(3) DEFAULT NULL,
  `next_attempt_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `attempt_count` int unsigned NOT NULL DEFAULT '0',
  `last_error_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_error_detail` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `row_version` bigint unsigned NOT NULL DEFAULT '1',
  `created_by` char(26) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `started_at` datetime(3) DEFAULT NULL,
  `heartbeat_at` datetime(3) DEFAULT NULL,
  `cancel_requested_at` datetime(3) DEFAULT NULL,
  `finished_at` datetime(3) DEFAULT NULL,
  `expires_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_operation_jobs_idem_domain` (`idempotency_domain`,`job_type`,`idempotency_key`),
  KEY `idx_operation_jobs_due` (`job_type`,`status`,`next_attempt_at`,`lease_expires_at`,`id`),
  KEY `idx_operation_jobs_tenant_created` (`tenant_id`,`job_type`,`created_at`,`id`),
  KEY `fk_operation_jobs_creator` (`created_by`),
  CONSTRAINT `fk_operation_jobs_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_operation_jobs_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `operation_jobs_chk_1` CHECK ((`status` in ('queued','running','paused','validating','cancel_requested','succeeded','failed','canceled'))),
  CONSTRAINT `operation_jobs_chk_2` CHECK (((`progress_total` is null) or (`progress_done` <= `progress_total`))),
  CONSTRAINT `operation_jobs_chk_3` CHECK (((`lease_owner` is null) = (`lease_token` is null))),
  CONSTRAINT `operation_jobs_chk_4` CHECK (((`lease_owner` is null) = (`lease_expires_at` is null))),
  CONSTRAINT `operation_jobs_chk_5` CHECK (((`status` in ('running','validating','cancel_requested')) = (`lease_owner` is not null))),
  CONSTRAINT `operation_jobs_chk_6` CHECK (((`status` in ('succeeded','failed','canceled')) = (`finished_at` is not null))),
  CONSTRAINT `operation_jobs_chk_scope` CHECK (((`scope_type` = 'tenant') and (`tenant_id` is not null)) or ((`scope_type` = 'system') and (`tenant_id` is null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `permissions` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subject_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subject_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `actions_json` json NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_permissions_subject_resource` (`tenant_id`,`subject_type`,`subject_id`,`resource_type`,`resource_id`),
  KEY `idx_permissions_resource` (`tenant_id`,`resource_type`,`resource_id`),
  CONSTRAINT `fk_permissions_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `permissions_chk_1` CHECK ((`subject_type` in ('user','role'))),
  CONSTRAINT `permissions_chk_2` CHECK ((`resource_type` in ('tenant','target','port','export_task','billing_account','billing_period')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `port_policies` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `port_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `side_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `billing_base_bps` bigint unsigned NOT NULL,
  `sample_step_seconds` smallint unsigned NOT NULL,
  `correction_direction` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `correction_min` bigint NOT NULL DEFAULT '0',
  `correction_max` bigint NOT NULL DEFAULT '0',
  `enabled` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_port_policies_port` (`tenant_id`,`port_id`),
  KEY `fk_port_policies_port` (`port_id`),
  CONSTRAINT `fk_port_policies_port` FOREIGN KEY (`port_id`) REFERENCES `network_ports` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_port_policies_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `port_policies_chk_1` CHECK ((`side_type` in ('provider','customer'))),
  CONSTRAINT `port_policies_chk_2` CHECK ((`sample_step_seconds` in (60,300))),
  CONSTRAINT `port_policies_chk_3` CHECK ((`correction_direction` in ('none','up','down'))),
  CONSTRAINT `port_policies_chk_4` CHECK ((`correction_min` >= 0)),
  CONSTRAINT `port_policies_chk_5` CHECK ((`correction_max` >= `correction_min`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

